<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
const props = defineProps({ settings: { type: String, default: '{}' }, updateUrl: String, csrf: String, success: String, error: String, theme: String, storageRoot: String, timezones: String });
const savedMessage=ref(props.success||'');const errorMessage=ref(props.error||'');const saving=ref(false);const dirty=ref(false);
let saved = {}; try { saved = JSON.parse(props.settings || '{}'); } catch {}
const value = key => saved[key] ?? ({ site_name: 'SecondBook', currency: 'USD', timezone: 'UTC', default_order_status: 'pending', order_number_format: 'SB-{YYYY}-{####}', cancel_order_period: 24, default_payment_method: 'cash_on_delivery', login_attempt_limit: 5, session_lifetime: 120, minimum_password_length: 8, default_shipping_fee: '0', free_shipping_threshold: '0', minimum_order_amount: '0', default_country: saved.country || '', estimated_delivery_message: 'Delivered within 3-5 business days' }[key] ?? '');
const sections = [
 {id:'sec-general',icon:'bi-globe',tone:'blue',label:'General',title:'Brand and location',desc:'Configure the basic identity and location of your marketplace.'},
 {id:'sec-store',icon:'bi-shop',tone:'green',label:'Store',title:'Marketplace settings',desc:'Control marketplace features and seller participation.'},
 {id:'sec-orders',icon:'bi-bag-check',tone:'amber',label:'Orders',title:'Order preferences',desc:'Set order defaults and customer notifications.'},
 {id:'sec-payments',icon:'bi-credit-card-2-front',tone:'blue',label:'Payments',title:'Payment options',desc:'Manage enabled payment methods.'},
 {id:'sec-shipping',icon:'bi-truck',tone:'cyan',label:'Shipping',title:'Shipping preferences',desc:'Configure shipping rates and delivery information.'},
 {id:'sec-seo',icon:'bi-search',tone:'violet',label:'SEO',title:'Search and metadata',desc:'Configure search visibility and analytics tags.'},
 {id:'sec-social',icon:'bi-share',tone:'rose',label:'Social',title:'Social profiles',desc:'Connect your marketplace social channels.'},
 {id:'sec-security',icon:'bi-shield-lock',tone:'red',label:'Security',title:'Security preferences',desc:'Set account protection and session rules.'},
 {id:'sec-legal',icon:'bi-file-earmark-text',tone:'slate',label:'Legal',title:'Policies and notices',desc:'Manage the legal information displayed to customers and sellers.'},
];
const activeTheme = ref(document.documentElement.getAttribute('data-theme') || props.theme || 'light');
const activeRail = ref('sec-appearance');
function setTheme(theme) { activeTheme.value=theme;dirty.value=true; document.documentElement.setAttribute('data-theme',theme); try { localStorage.setItem('admin_theme',theme); } catch {} }
let railObserver; const railLinks=[];
function scrollToSection(event){event.preventDefault();const id=event.currentTarget.dataset.rail;document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'});activeRail.value=id;history.replaceState(null,'',`#${id}`)}
onMounted(()=>{document.querySelectorAll('.settings-page [data-rail]').forEach(link=>{link.addEventListener('click',scrollToSection);railLinks.push(link)});if('IntersectionObserver' in window){railObserver=new IntersectionObserver(entries=>{const visible=entries.filter(entry=>entry.isIntersecting).sort((a,b)=>a.boundingClientRect.top-b.boundingClientRect.top);if(visible[0])activeRail.value=visible[0].target.id},{rootMargin:'-20% 0px -70% 0px'});document.querySelectorAll('.settings-page [data-rail]').forEach(link=>{const section=document.getElementById(link.dataset.rail);if(section)railObserver.observe(section)})}});
onBeforeUnmount(()=>{railObserver?.disconnect();railLinks.forEach(link=>link.removeEventListener('click',scrollToSection))});
let paymentMethods=[]; try { paymentMethods=JSON.parse(value('payment_methods') || '[]'); if(!Array.isArray(paymentMethods)) paymentMethods=[]; } catch { paymentMethods=[]; }
const methods=['cash_on_delivery','credit_card','debit_card','paypal'];
const fileUrls = computed(() => ({logo:saved.logo ? `${props.storageRoot}/${saved.logo}` : '', favicon:saved.favicon ? `${props.storageRoot}/${saved.favicon}` : '', open_graph_image:saved.open_graph_image ? `${props.storageRoot}/${saved.open_graph_image}` : ''}));
function preview(event) { const input=event.target; const file=input.files?.[0]; const box=input.closest('[data-file]'); if(!box) return; box.classList.toggle('has-file',!!file); const name=box.querySelector('[data-file-name]'); const img=box.querySelector('img'); const icon=box.querySelector('.sx-file-thumb i'); if(file){name.textContent=`${file.name} — ${Math.max(1,Math.round(file.size/1024))} KB`; const reader=new FileReader(); reader.onload=e=>{img.src=e.target.result;img.hidden=false;if(icon)icon.hidden=true};reader.readAsDataURL(file);} }
function dropFile(event){event.currentTarget.classList.remove('is-dragover');const input=event.currentTarget.querySelector('input[type=file]');if(event.dataTransfer?.files?.length&&input){input.files=event.dataTransfer.files;input.dispatchEvent(new Event('change',{bubbles:true}))}}
async function save(event){const form=event.currentTarget;saving.value=true;errorMessage.value='';savedMessage.value='';try{const response=await fetch(form.action,{method:'POST',body:new FormData(form),credentials:'same-origin',headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}});let result={};try{result=await response.json()}catch{}if(!response.ok){const messages=Object.values(result.errors||{}).flat();throw new Error(messages.join('\n')||result.message||'Please review the settings form.')}savedMessage.value=result.message||'Settings updated successfully.';dirty.value=false;if(window.Swal)window.Swal.fire({icon:'success',title:'Settings saved',text:savedMessage.value,confirmButtonColor:'#3451d1',confirmButtonText:'Done',customClass:{popup:'settings-swal-popup'}})}catch(e){errorMessage.value=e.message||'Something went wrong while saving settings.';if(window.Swal)window.Swal.fire({icon:'error',title:'Save failed',text:errorMessage.value,confirmButtonColor:'#3451d1',confirmButtonText:'Try again',customClass:{popup:'settings-swal-popup'}})}finally{saving.value=false}}
function label(key){return key.replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase())}
const toggles={maintenance_mode:'Maintenance mode', marketplace_enabled:'Marketplace enabled',user_registration_enabled:'User registration enabled',seller_registration_enabled:'Seller registration enabled',seller_approval_required:'Require seller approval',book_approval_required:'Require book approval',reviews_enabled:'Reviews enabled',stock_management_enabled:'Stock management enabled',auto_cancel_pending_orders:'Automatically cancel pending orders',customer_order_notifications:'Customer order notifications',payments_enabled:'Payments enabled',shipping_enabled:'Shipping enabled',search_engine_indexing:'Search engine indexing enabled',two_factor_authentication_enabled:'Two-factor authentication',admin_session_security:'Admin session security'};
function enabled(key, def=!(key==='maintenance_mode'||key==='two_factor_authentication_enabled'||key==='admin_session_security')){const v=value(key);return v===''?def:(v===true||v===1||v==='1'||v==='true');}
const sectionsFields={
 'sec-general':[['site_name','text','Site name','bi-fonts','SecondBook','required'],['support_email','email','Support email','bi-envelope'],['site_description','textarea','Site description'],['support_phone','text','Support phone','bi-telephone'],['address','text','Address','bi-geo-alt'],['country','text','Country','bi-flag'],['city','text','City','bi-building'],['currency','text','Currency','bi-cash-coin','USD','required'],['timezone','timezone','Timezone','bi-clock'],['logo','file','Logo','bi-image'],['favicon','file','Favicon','bi-image']],
 'sec-store':[['minimum_order_amount','number','Minimum order amount','bi-cash','0','min="0" step="0.01"']],
 'sec-orders':[['default_order_status','select','Default order status','bi-bag-check',['pending','processing','shipped','delivered','cancelled']],['order_number_format','text','Order number format','bi-hash','SB-{YYYY}-{####}'],['cancel_order_period','number','Cancel order period (hours)','bi-clock','24','min="0" max="720"']],
 'sec-payments':[['default_payment_method','select','Default payment method','bi-credit-card',methods]],
 'sec-shipping':[['default_shipping_fee','number','Default shipping fee','bi-truck','0','min="0" step="0.01"'],['free_shipping_threshold','number','Free shipping threshold','bi-gift','0','min="0" step="0.01"'],['default_country','text','Default country','bi-geo-alt'],['estimated_delivery_message','text','Estimated delivery message','bi-chat-left-text','Delivered within 3-5 business days']],
 'sec-seo':[['meta_title','text','Meta title','bi-type'],['keywords','text','Keywords','bi-tags'],['meta_description','textarea','Meta description'],['open_graph_image','file','Open Graph image','bi-image'],['google_analytics_id','text','Google Analytics ID','bi-graph-up'],['google_search_console_verification','text','Google Search Console verification','bi-google']],
 'sec-social':[['facebook','url','Facebook','bi-facebook'],['instagram','url','Instagram','bi-instagram'],['tiktok','url','TikTok','bi-tiktok'],['youtube','url','YouTube','bi-youtube'],['whatsapp','text','WhatsApp','bi-whatsapp']],
 'sec-security':[['login_attempt_limit','number','Login attempt limit','bi-shield','5','min="1" max="20"'],['session_lifetime','number','Session lifetime (minutes)','bi-hourglass','120','min="1" max="10080"'],['minimum_password_length','number','Minimum password length','bi-key','8','min="8" max="128"']],
 'sec-legal':[['privacy_policy','textarea','Privacy Policy'],['terms_conditions','textarea','Terms & Conditions'],['refund_policy','textarea','Refund Policy'],['shipping_policy','textarea','Shipping Policy'],['cookie_notice','textarea','Cookie Notice']],
};
let currencyTimezones=['UTC','Asia/Baku','Europe/London','America/New_York'];try{currencyTimezones=JSON.parse(props.timezones||'[]')}catch{}
</script>

<template>
<div class="dashboard-section settings-page">
 <div class="settings-hero"><div class="settings-hero-content"><div class="settings-hero-crumb"><i class="bi bi-sliders"></i> Administration</div><h1>Settings</h1><p>Configure your SecondBook marketplace, appearance, payments, shipping, security and platform preferences from one place.</p></div><div class="settings-hero-icon"><i class="bi bi-gear-fill"></i></div></div>
 <div v-if="savedMessage" class="settings-alert settings-alert-success"><i class="bi bi-check-circle-fill"></i><div class="settings-alert-body"><span>{{ savedMessage }}</span></div></div><div v-if="errorMessage" class="settings-alert settings-alert-error"><i class="bi bi-exclamation-triangle-fill"></i><div class="settings-alert-body"><strong>Please review the settings form.</strong><span>{{ errorMessage }}</span></div></div>
 <div class="sx-layout"><nav class="sx-rail" aria-label="Settings sections"><div class="sx-rail-title">Sections</div><a v-for="s in [{id:'sec-appearance',icon:'bi-palette',tone:'violet',label:'Appearance'},...sections]" :key="s.id" :href="'#'+s.id" :class="['sx-tone-'+s.tone,{ 'is-active':activeRail===s.id }]" :data-rail="s.id"><i :class="['bi',s.icon]"></i><span>{{ s.label }}</span></a></nav>
 <div class="sx-content"><section class="settings-card settings-theme-card" id="sec-appearance"><div class="settings-card-header"><div class="settings-card-heading"><span class="sx-chip sx-tone-violet"><i class="bi bi-palette"></i></span><div><h2>Theme mode</h2><p>Choose how the admin interface appears on this browser.</p></div></div></div><div class="settings-theme-options"><button type="button" :class="['settings-theme-option','theme-select-btn',{active:activeTheme==='light'}]" @click="setTheme('light')"><div class="settings-theme-preview settings-theme-preview-light"><div class="tp-side"></div><div class="tp-main"><div class="tp-bar"></div><div class="tp-line"></div><div class="tp-line"></div><div class="tp-line"></div></div></div><div class="settings-theme-info"><div><strong>Light mode</strong><small>Classic bright interface</small></div><div class="settings-theme-check"><i class="bi bi-sun"></i></div></div></button><button type="button" :class="['settings-theme-option','theme-select-btn',{active:activeTheme==='dark'}]" @click="setTheme('dark')"><div class="settings-theme-preview settings-theme-preview-dark"><div class="tp-side"></div><div class="tp-main"><div class="tp-bar"></div><div class="tp-line"></div><div class="tp-line"></div><div class="tp-line"></div></div></div><div class="settings-theme-info"><div><strong>Dark mode</strong><small>Comfortable low-light interface</small></div><div class="settings-theme-check"><i class="bi bi-moon-stars"></i></div></div></button></div></section>
 <form id="settingsForm" method="POST" :action="updateUrl" enctype="multipart/form-data" @submit.prevent="save" @input="dirty=true" @change="dirty=true"><input type="hidden" name="_token" :value="csrf"><input type="hidden" name="_method" value="PUT"><input type="hidden" name="theme" :value="activeTheme"><div class="settings-save-header"><div><h2>Global settings</h2><p>Manage how SecondBook behaves across the marketplace.</p></div><button class="settings-primary-btn" type="submit" :disabled="saving"><i v-if="!saving" class="bi bi-check2-circle"></i><span>{{ saving ? 'Saving…' : 'Save settings' }}</span></button></div>
 <section v-for="section in sections" :id="section.id" :key="section.id" class="settings-card settings-section"><div class="settings-card-header"><div class="settings-card-heading"><span :class="['sx-chip','sx-tone-'+section.tone]"><i :class="['bi',section.icon]"></i></span><div><h2>{{ section.title }}</h2><p>{{ section.desc }}</p></div></div></div>
 <div v-if="section.id==='sec-general'" class="settings-grid"><div v-for="f in sectionsFields[section.id].filter(field => !(section.id === 'sec-payments' && field[0] === 'default_payment_method'))" :key="f[0]" :class="['settings-field',f[1]==='textarea'?'settings-field-full':'']"><label :for="f[0]">{{ f[2] }}</label><template v-if="f[1]==='file'"><div class="sx-file" data-file @dragenter.prevent="event.currentTarget.classList.add('is-dragover')" @dragover.prevent="event.currentTarget.classList.add('is-dragover')" @dragleave="event.currentTarget.classList.remove('is-dragover')" @drop.prevent="dropFile"><input class="sx-file-input" :id="f[0]" type="file" :name="f[0]" accept="image/*" @change="preview"><label class="sx-file-drop" :for="f[0]"><span class="sx-file-thumb"><i :class="['bi',f[3]]" :hidden="!!fileUrls[f[0]]"></i><img v-if="fileUrls[f[0]]" :src="fileUrls[f[0]]" alt="Current image"><img v-else alt="" hidden></span><span class="sx-file-text"><strong>Choose an image</strong><span class="sx-file-name" data-file-name>Drop a file here or browse</span></span><span class="sx-file-btn"><i class="bi bi-upload"></i> Browse</span></label></div></template><template v-else-if="f[1]==='textarea'"><textarea class="sx-area" :id="f[0]" :name="f[0]" rows="3">{{ value(f[0]) }}</textarea></template><div v-else class="sx-input"><i :class="['bi',f[3]]"></i><select v-if="f[1]==='timezone'" :id="f[0]" :name="f[0]" required><option v-for="tz in currencyTimezones" :key="tz" :value="tz" :selected="tz===value(f[0])">{{ tz }}</option></select><input v-else :id="f[0]" :type="f[1]" :name="f[0]" :value="value(f[0]) || f[4] || ''" :required="f[5]==='required'" :min="f[5]?.includes('min=') ? (f[0].includes('amount')||f[0].includes('fee')||f[0].includes('threshold')?'0':'1') : null" :max="f[0]==='cancel_order_period'?'720':f[0]==='session_lifetime'?'10080':f[0]==='login_attempt_limit'?'20':f[0]==='minimum_password_length'?'128':null" :step="f[5]?.includes('step=')?'0.01':null"></div></div></div>
 <div v-else class="settings-grid"><template v-if="section.id==='sec-payments'"><div class="settings-field"><label for="default_payment_method">Default payment method</label><div class="sx-input"><i class="bi bi-credit-card"></i><select id="default_payment_method" name="default_payment_method" required><option v-for="method in methods" :key="method" :value="method" :selected="method===value('default_payment_method')">{{ label(method) }}</option></select></div></div><div class="settings-subsection settings-field-full"><div class="settings-subsection-heading"><h3>Accepted payment methods</h3></div><label v-for="method in methods" :key="method" class="form-check form-check-inline"><input class="form-check-input" type="checkbox" name="payment_methods[]" :value="method" :checked="paymentMethods.includes(method)"><span class="form-check-label">{{ label(method) }}</span></label></div></template>
 <div v-for="f in sectionsFields[section.id].filter(field => !(section.id === 'sec-payments' && field[0] === 'default_payment_method'))" :key="f[0]" :class="['settings-field',f[1]==='textarea'?'settings-field-half':'']"><label :for="f[0]">{{ f[2] }}</label><template v-if="f[1]==='textarea'"><textarea class="sx-area" :id="f[0]" :name="f[0]" rows="5">{{ value(f[0]) }}</textarea></template><template v-else-if="f[1]==='select'"><div class="sx-input"><i :class="['bi',f[3]]"></i><select :id="f[0]" :name="f[0]" required><option v-for="option in f[4]" :key="option" :value="option" :selected="option===value(f[0])">{{ label(option) }}</option></select></div></template><template v-else-if="f[1]==='file'"><div class="sx-file" data-file @dragenter.prevent="event.currentTarget.classList.add('is-dragover')" @dragover.prevent="event.currentTarget.classList.add('is-dragover')" @dragleave="event.currentTarget.classList.remove('is-dragover')" @drop.prevent="dropFile"><input class="sx-file-input" :id="f[0]" type="file" :name="f[0]" accept="image/*" @change="preview"><label class="sx-file-drop" :for="f[0]"><span class="sx-file-thumb"><i :class="['bi',f[3]]" :hidden="!!fileUrls[f[0]]"></i><img v-if="fileUrls[f[0]]" :src="fileUrls[f[0]]" alt="Current image"><img v-else alt="" hidden></span><span class="sx-file-text"><strong>Choose an image</strong><span class="sx-file-name" data-file-name>Drop a file here or browse</span></span><span class="sx-file-btn"><i class="bi bi-upload"></i> Browse</span></label></div></template><div v-else class="sx-input"><i :class="['bi',f[3]]"></i><input :id="f[0]" :type="f[1]" :name="f[0]" :value="value(f[0]) || f[4] || ''" :required="f[5]==='required'" :min="f[1]==='number'?(f[0]==='cancel_order_period'?'0':f[0]==='login_attempt_limit'?'1':f[0]==='session_lifetime'?'1':f[0]==='minimum_password_length'?'8':'0'):null" :max="f[0]==='cancel_order_period'?'720':f[0]==='session_lifetime'?'10080':f[0]==='login_attempt_limit'?'20':f[0]==='minimum_password_length'?'128':null" :step="f[1]==='number' && ['minimum_order_amount','default_shipping_fee','free_shipping_threshold'].includes(f[0])?'0.01':null"></div></div>
 <div v-if="Object.keys(toggles).some(key=> (section.id==='sec-general'&&key==='maintenance_mode')||(section.id==='sec-store'&&['marketplace_enabled','user_registration_enabled','seller_registration_enabled','seller_approval_required','book_approval_required','reviews_enabled','stock_management_enabled'].includes(key))||(section.id==='sec-orders'&&['auto_cancel_pending_orders','customer_order_notifications'].includes(key))||(section.id==='sec-payments'&&key==='payments_enabled')||(section.id==='sec-shipping'&&key==='shipping_enabled')||(section.id==='sec-seo'&&key==='search_engine_indexing')||(section.id==='sec-security'&&['two_factor_authentication_enabled','admin_session_security'].includes(key)))" class="settings-toggle-grid settings-field-full"><div v-for="(title,key) in toggles" v-show="(section.id==='sec-general'&&key==='maintenance_mode')||(section.id==='sec-store'&&['marketplace_enabled','user_registration_enabled','seller_registration_enabled','seller_approval_required','book_approval_required','reviews_enabled','stock_management_enabled'].includes(key))||(section.id==='sec-orders'&&['auto_cancel_pending_orders','customer_order_notifications'].includes(key))||(section.id==='sec-payments'&&key==='payments_enabled')||(section.id==='sec-shipping'&&key==='shipping_enabled')||(section.id==='sec-seo'&&key==='search_engine_indexing')||(section.id==='sec-security'&&['two_factor_authentication_enabled','admin_session_security'].includes(key))" :key="key" class="settings-toggle-card"><div class="settings-toggle-info"><span class="sx-chip sx-chip-sm sx-tone-blue"><i class="bi bi-toggles"></i></span><div><strong>{{ title }}</strong><small>Enable or disable this marketplace option.</small></div></div><label class="settings-toggle"><input type="checkbox" :name="key" value="1" :checked="enabled(key)"><i></i></label></div></div>
 </div></section>
 <div :class="['settings-save-bar',{ 'is-dirty':dirty }]" id="settingsSaveBar"><div class="settings-save-info"><span class="settings-save-dot"></span><div><strong>{{ dirty ? 'Unsaved changes' : 'All changes saved' }}</strong><small>{{ dirty ? 'Save to apply your edits.' : 'Changes apply after saving.' }}</small></div></div><button class="settings-primary-btn" type="submit" :disabled="saving"><i v-if="!saving" class="bi bi-check2-circle"></i><span>{{ saving ? 'Saving…' : 'Save all settings' }}</span></button></div></form></div></div>
</div>
</template>
